def test_mgga_xc_zlp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_xc_zlp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.693500684295438e+00, -5.239757214612768e+00, -4.863896295151754e+00, -4.519593632294606e+00, -4.168537500548279e+00, -3.778651212333615e+00, -3.325472770652897e+00, -2.797454028105644e+00, -2.204716440273415e+00, -1.583647567827356e+00, -9.725972890896992e-01, -6.599353779243295e-01, -6.312604909236444e-01, -5.133090404773998e-01, -3.554669262049630e-01, -2.112649669804994e-01, -1.182661519325001e-01, -1.014330229955937e-01, -2.540561726322634e-01, -1.533815719925632e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


